-- PostgreSQL 18 plans a locking clause as a LockRows node above the query's
-- sort and below its Limit (grouping_planner); a subquery that locks keeps
-- its Subquery Scan, and a query without FROM has no rows to lock. Under
-- ANALYZE the node counts the rows it locked and returned.
CREATE TABLE t470 (a int, b int);
INSERT INTO t470 SELECT g % 10, g FROM generate_series(1, 100) g;
CREATE TABLE u470 (a int, c text);
INSERT INTO u470 SELECT g, 'x' || g FROM generate_series(1, 20) g;
ANALYZE t470;
ANALYZE u470;
EXPLAIN (COSTS OFF) SELECT * FROM t470 FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM t470 WHERE a = 1 FOR SHARE;
EXPLAIN (COSTS OFF) SELECT * FROM t470 JOIN u470 ON t470.b = u470.a FOR UPDATE OF t470;
EXPLAIN (COSTS OFF) SELECT * FROM t470 ORDER BY b LIMIT 1 FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM t470 ORDER BY b LIMIT 1 FOR NO KEY UPDATE SKIP LOCKED;
EXPLAIN (COSTS OFF) SELECT * FROM t470 ORDER BY b OFFSET 2 FOR KEY SHARE;
EXPLAIN (COSTS OFF) SELECT * FROM t470 FOR UPDATE OF t470 NOWAIT;
EXPLAIN (COSTS OFF) SELECT * FROM (SELECT * FROM t470 FOR UPDATE) s;
EXPLAIN (COSTS OFF) SELECT * FROM (SELECT * FROM t470 WHERE a = 2 FOR UPDATE) s WHERE b > 50;
EXPLAIN (COSTS OFF) SELECT 1 FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM (VALUES (1), (2)) v FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM t470 WHERE false FOR UPDATE;
EXPLAIN (COSTS OFF, FORMAT JSON) SELECT * FROM t470 WHERE a = 1 FOR UPDATE;
EXPLAIN (COSTS OFF, FORMAT YAML) SELECT * FROM t470 ORDER BY b LIMIT 2 FOR UPDATE;
CREATE FUNCTION analyzed470(query text) RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE
  line text;
BEGIN
  FOR line IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) ' || query LOOP
    -- Memory figures are each server's own.
    RETURN NEXT regexp_replace(line, '(Memory|Memory Usage): \d+kB', '\1: NkB');
  END LOOP;
END
$$;
SELECT analyzed470('SELECT * FROM t470 WHERE a = 1 FOR UPDATE');
SELECT analyzed470('SELECT * FROM t470 WHERE a = 1 ORDER BY b OFFSET 3 LIMIT 4 FOR UPDATE');
SELECT analyzed470('SELECT * FROM t470 WHERE a < 3 ORDER BY b DESC FOR SHARE');
SELECT analyzed470('SELECT * FROM t470 WHERE false FOR UPDATE');
SELECT analyzed470('SELECT * FROM (SELECT * FROM t470 WHERE b > 95 FOR UPDATE) s');
SELECT * FROM t470 WHERE a = 1 FETCH FIRST 2 ROWS WITH TIES FOR UPDATE;
